export function scrabbleScore(word) {
    const values = { 1: 'AEIOULNRST', 2: 'DG', 3: 'BCMP', 4: 'FHVWY', 5: 'K', 8: 'JX', 10: 'QZ' };
    let sum = 0;
    for (const c of word.toUpperCase())
        for (const [value, letters] of Object.entries(values))
            if (letters.includes(c))
                sum += Number(value);
    return sum;
}
